const b = $input.first().json.body ?? {};
const str = (v, max) => (typeof v === 'string' ? v.trim().slice(0, max) : '');
const num = (v) => {
  if (v === '' || v === null || v === undefined) return null;
  const n = Number(v);
  return Number.isFinite(n) ? n : null;
};
const round1 = (n) => Math.round(n * 10) / 10;

const action = str(b.action, 30);
const token = str(b.access_token, 4096);
const errors = [];

if (!['get_profile', 'save_profile', 'generate', 'history'].includes(action)) errors.push('Invalid action.');
if (token.length < 20) errors.push('You are not signed in.');

let profile = null;
let request = null;

// ---------- save_profile ----------
if (action === 'save_profile') {
  const age = num(b.age);
  const height = num(b.height_cm);
  const weight = num(b.weight_kg);
  const goal = str(b.goal, 30);
  const level = str(b.experience_level, 30);
  const injuries = str(b.injuries, 500);
  const diet = str(b.diet_preference, 300);

  if (age === null || age < 12 || age > 90) errors.push('Age must be between 12 and 90.');
  if (height === null || height < 120 || height > 230) errors.push('Height must be between 120 and 230 cm.');
  if (weight === null || weight < 30 || weight > 250) errors.push('Weight must be between 30 and 250 kg.');
  if (!['fat_loss', 'muscle_gain', 'strength', 'endurance', 'general_fitness'].includes(goal)) errors.push('Choose a valid goal.');
  if (!['beginner', 'intermediate', 'advanced'].includes(level)) errors.push('Choose a valid experience level.');

  if (errors.length === 0) {
    const bmi = round1(weight / Math.pow(height / 100, 2));
    const inj = injuries.toLowerCase();
    const noInjury = ['', 'none', 'no', 'nothing', 'n/a', 'لا', 'لا يوجد', 'لا شيء'].includes(inj);
    const flags = [];
    if (age < 18) flags.push('under_18');
    if (bmi < 17) flags.push('very_low_bmi');
    if (bmi >= 35) flags.push('high_bmi');
    if (!noInjury) flags.push('has_injury');
    if (inj.includes('knee') || inj.includes('ركب')) flags.push('knee_injury');
    if (inj.includes('back') || inj.includes('ظهر')) flags.push('back_injury');
    if (inj.includes('shoulder') || inj.includes('كتف')) flags.push('shoulder_injury');

    profile = {
      age: Math.round(age),
      height_cm: round1(height),
      weight_kg: round1(weight),
      bmi,
      goal,
      experience_level: level,
      injuries: noInjury ? null : injuries,
      diet_preference: diet || null,
      risk_flags: flags,
      updated_at: new Date().toISOString()
    };
  }
}

// ---------- generate ----------
if (action === 'generate') {
  const planType = str(b.plan_type, 10);
  const days = parseInt(b.days_per_week, 10);
  const minutes = parseInt(b.session_minutes, 10);
  const equipment = str(b.equipment, 20);

  if (!['workout', 'meal', 'both'].includes(planType)) errors.push('Choose workout, meal or both.');
  if (!(days >= 2 && days <= 6)) errors.push('Days per week must be between 2 and 6.');
  if (![30, 45, 60, 90].includes(minutes)) errors.push('Choose a valid session length.');
  if (!['none', 'dumbbells', 'full_gym'].includes(equipment)) errors.push('Choose valid equipment.');

  request = {
    plan_type: planType,
    days_per_week: days,
    session_minutes: minutes,
    equipment,
    include_nutrition: ['true', 'on', '1', 'yes'].includes(String(b.include_nutrition ?? '').toLowerCase()),
    notes: str(b.notes, 500)
  };
}

return [{ json: { valid: errors.length === 0, errors, action, token, profile, request } }];

