const out = $input.first().json.output ?? {};
const memberId = $('Verify Token').first().json.body.id;
const req = $('Validate Input').first().json.request;
const isObj = (v) => v !== null && typeof v === 'object' && !Array.isArray(v);
const hasDays = (p) => isObj(p) && Array.isArray(p.days) && p.days.length > 0;
const notes = req.notes || null;
const rows = [];

if (['workout', 'both'].includes(req.plan_type) && hasDays(out.workout_plan)) {
  const plan = { ...out.workout_plan, days: out.workout_plan.days.slice(0, req.days_per_week) };
  rows.push({ member_id: memberId, plan_type: 'workout', content: plan, nutrition_estimate: null, request_notes: notes });
}

if (['meal', 'both'].includes(req.plan_type) && hasDays(out.meal_plan)) {
  const estimate = req.include_nutrition && isObj(out.nutrition_estimate) ? out.nutrition_estimate : null;
  rows.push({ member_id: memberId, plan_type: 'meal', content: out.meal_plan, nutrition_estimate: estimate, request_notes: notes });
}

return [{
  json: {
    rows,
    has_rows: rows.length > 0,
    status: out.status === 'needs_info' ? 'needs_info' : 'ok',
    message: String(out.message ?? '').slice(0, 1500)
  }
}];

